package autothreshold

import (
	"encoding/json"
	"math"
	"os"
	"testing"
)

// skimageFixture is testdata/upstream/skimage/thresholds.json, generated by
// dicom-go-validation/scripts/skimage_threshold_fixtures.py with
// scikit-image 0.26.0 on synthetic integer histograms.
type skimageFixture struct {
	SkimageVersion string `json:"skimage_version"`
	Cases          []struct {
		Name       string    `json:"name"`
		Min        int       `json:"min"`
		Counts     []float64 `json:"counts"`
		Otsu       *float64  `json:"otsu"`
		Li         *float64  `json:"li"`
		Yen        *float64  `json:"yen"`
		IsoData    *float64  `json:"isodata"`
		Triangle   *float64  `json:"triangle"`
		Mean       *float64  `json:"mean"`
		Minimum    *float64  `json:"minimum"`
		MultiOtsu3 []float64 `json:"multiotsu3"`
		MultiOtsu4 []float64 `json:"multiotsu4"`
	} `json:"cases"`
}

func loadSkimageFixture(t *testing.T) skimageFixture {
	t.Helper()
	data, err := os.ReadFile("../../testdata/upstream/skimage/thresholds.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture skimageFixture
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Cases) == 0 {
		t.Fatal("fixture has no cases")
	}
	return fixture
}

// TestThresholdsMatchScikitImage compares the class partitions with
// scikit-image: its threshold t (foreground image > t) must select the same
// lower class, the unit bins whose value is <= t.
func TestThresholdsMatchScikitImage(t *testing.T) {
	fixture := loadSkimageFixture(t)
	for _, c := range fixture.Cases {
		t.Run(c.Name, func(t *testing.T) {
			lower := float64(c.Min) - 0.5
			h, err := NewHistogramFromCounts(c.Counts, lower, lower+float64(len(c.Counts)))
			if err != nil {
				t.Fatal(err)
			}
			// Rebuilding the histogram from the samples with unit bins gives
			// the same bins.
			samples := make([]float64, 0, int(h.Total()))
			for i, n := range c.Counts {
				for j := 0; j < int(n); j++ {
					samples = append(samples, float64(c.Min+i))
				}
			}
			rebuilt, err := NewHistogram(SliceValues(samples), HistogramOptions{BinWidth: 1})
			if err != nil || rebuilt.Lower != h.Lower || rebuilt.Bins() != h.Bins() {
				t.Fatalf("unit-bin histogram = %+v, %v; want lower %v, %d bins", rebuilt, err, h.Lower, h.Bins())
			}
			wantBin := func(value float64) int { return int(math.Floor(value)) - c.Min }
			for _, check := range []struct {
				method Method
				want   *float64
			}{
				{Otsu, c.Otsu}, {Li, c.Li}, {Yen, c.Yen}, {IsoData, c.IsoData},
				{Triangle, c.Triangle}, {Mean, c.Mean}, {Minimum, c.Minimum},
			} {
				got, err := rebuilt.Threshold(check.method)
				if check.want == nil {
					if err == nil {
						t.Logf("%s: scikit-image raised, dicom-go split at bin %d", check.method, got.Bin)
					}
					continue
				}
				if err != nil {
					t.Errorf("%s: %v (scikit-image %v)", check.method, err, *check.want)
					continue
				}
				if want := wantBin(*check.want); got.Bin != want {
					t.Errorf("%s: split after value %v, scikit-image %v (bin %d)", check.method, got.Center, *check.want, want)
				}
				if got.Value != got.Center+0.5 {
					t.Errorf("%s: boundary %v, want centre+0.5 for unit bins", check.method, got.Value)
				}
			}
			// scikit-image 0.26.0 places the second and third multi-Otsu
			// thresholds of some cases one bin below the exhaustive optimum.
			// The split must be the exhaustive optimum, at least as good as
			// scikit-image's, and within one bin of it (equal for the first).
			for classes, want := range map[int][]float64{3: c.MultiOtsu3, 4: c.MultiOtsu4} {
				got, err := rebuilt.MultiOtsu(classes)
				if err != nil {
					t.Fatalf("MultiOtsu(%d): %v", classes, err)
				}
				if len(got) != len(want) {
					t.Fatalf("MultiOtsu(%d) = %d thresholds, want %d", classes, len(got), len(want))
				}
				bins := make([]int, len(got))
				skimageBins := make([]int, len(want))
				for i := range want {
					bins[i], skimageBins[i] = got[i].Bin, wantBin(want[i])
					if d := bins[i] - skimageBins[i]; d < -1 || d > 1 || (i == 0 && d != 0) {
						t.Errorf("MultiOtsu(%d)[%d]: split after %v, scikit-image %v", classes, i, got[i].Center, want[i])
					}
				}
				score, skimageScore := otsuScore(rebuilt.Counts, bins), otsuScore(rebuilt.Counts, skimageBins)
				if score < skimageScore {
					t.Errorf("MultiOtsu(%d) score %v below scikit-image's %v", classes, score, skimageScore)
				}
				if best := exhaustiveOtsu(rebuilt.Counts, classes); score < best*(1-1e-12) {
					t.Errorf("MultiOtsu(%d) score %v below the exhaustive optimum %v", classes, score, best)
				}
			}
		})
	}
}

// otsuScore is sum(S_c^2/P_c) over the classes split after the given bins,
// the multi-Otsu objective up to constants.
func otsuScore(counts []float64, splits []int) float64 {
	score, start := 0.0, 0
	for _, end := range append(append([]int(nil), splits...), len(counts)-1) {
		w, s := 0.0, 0.0
		for i := start; i <= end; i++ {
			w += counts[i]
			s += float64(i) * counts[i]
		}
		if w > 0 {
			score += s * s / w
		}
		start = end + 1
	}
	return score
}

// exhaustiveOtsu returns the best multi-Otsu objective over every split.
func exhaustiveOtsu(counts []float64, classes int) float64 {
	n := len(counts)
	P := make([]float64, n+1)
	S := make([]float64, n+1)
	for i, c := range counts {
		P[i+1], S[i+1] = P[i]+c, S[i]+float64(i)*c
	}
	term := func(a, b int) float64 {
		if w := P[b] - P[a]; w > 0 {
			s := S[b] - S[a]
			return s * s / w
		}
		return 0
	}
	var search func(start, left int) float64
	search = func(start, left int) float64 {
		if left == 1 {
			return term(start, n)
		}
		best := math.Inf(-1)
		for end := start + 1; end <= n-left+1; end++ {
			best = math.Max(best, term(start, end)+search(end, left-1))
		}
		return best
	}
	return search(0, classes)
}
